    document.querySelectorAll('[data-existing-restore]').forEach(button=>button.onclick=event=>{event.stopPropagation();const id=button.dataset.existingRestore;if(id)window.analysisRestoreRecord(id)});
    const archiveCsvFiles=async fileIds=>{const ids=new Set(fileIds||[]),toArchive=files.filter(file=>ids.has(file.id));if(!toArchive.length||A.restorePending)return;const list=toArchive.map(file=>'• '+file.name).join('\n');if(!confirm(`${uiText("להעביר לארכיון")} ${toArchive.length===1?uiText('את קובץ ה־CSV הזה'):'את '+toArchive.length+' קובצי ה־CSV האלה'}?\n\n${list}\n\nהקבצים יופיעו ב״שמירה וגיבוי״ → ״סל מחזור לקבצים״, ומשם אפשר לשחזר אותם.`))return;A.restorePending=true;A.existingFilesOpen=false;renderBody();let moved=0;try{for(const file of toArchive){await workspaceMutation({action:'delete-file',fileId:file.id});moved++}toast(toArchive.length===1?uiText('קובץ ה־CSV הועבר לארכיון. אפשר לשחזר אותו מסל המחזור.'):`${moved} ${uiText("קובצי CSV הועברו לארכיון. אפשר לשחזר אותם מסל המחזור.")}`)}catch(error){toast(`${moved} ${uiText("קבצים הועברו לארכיון; העברת היתר נכשלה:")} ${error.message}`,true)}finally{A.restorePending=false;A.existingFilesOpen=false;renderBody()}};
    document.querySelectorAll('[data-existing-archive]').forEach(button=>button.onclick=event=>{event.stopPropagation();archiveCsvFiles([button.dataset.existingArchive])});
