    const chapters=(S?.chapters||[]).filter(c=>c.paperId===paper.id),body=c=>String(c?.content??c?.text??c?.body??c?.draft??c?.notes??'').trim(),preferred=chapters.filter(c=>/(תקציר|מבוא|מטר|שאל|סקירה|מסגרת|מתודולוג|דיון|נספח|appendix)/i.test(c.title||'')),chapter=preferred.find(c=>body(c))||chapters.find(c=>body(c))||null;
    const paperFallback=[['תקציר',paper.abstract],['מטרה',paper.goal],['שאלות המחקר',paper.questions],['שיטה',paper.method],['תרומה צפויה',paper.contribution]].find(([,v])=>String(v||'').trim());
    const source=body(chapter)||String(paperFallback?.[1]||''),raw=source.replace(/```[\\s\\S]*?```/g,' ').replace(/[#>*_`|]/g,' ').replace(/\\s+/g,' ').trim();
