  function itemDescriptives(r){return r.items.map(name=>{const i=A.mapping.findIndex(m=>m.name===name),m=A.mapping[i];if(i<0||!m)return {name,n:0,missing:A.rows.length,mean:null,median:null,sd:null,variance:null,min:null,max:null,range:null,q1:null,q3:null,mode:null,reverse:false};const vals=A.rows.map(row=>{try{let x=mappedValue(row[i],m);return x!==null&&r.reverse.includes(name)?6-x:x}catch{return null}}),ok=vals.filter(Number.isFinite).sort((a,b)=>a-b),freq=new Map();ok.forEach(x=>freq.set(x,(freq.get(x)||0)+1));const mode=[...freq.entries()].sort((a,b)=>b[1]-a[1]||a[0]-b[0])[0]?.[0]??null,mean=ok.length?ok.reduce((a,b)=>a+b,0)/ok.length:null,variance=ok.length>1?ok.reduce((s,x)=>s+(x-mean)**2,0)/(ok.length-1):null;return {name,n:ok.length,missing:vals.length-ok.length,mean,median:ok.length?medianSorted(ok):null,sd:variance===null?null:Math.sqrt(variance),variance,min:ok.length?ok[0]:null,max:ok.length?ok.at(-1):null,range:ok.length?ok.at(-1)-ok[0]:null,q1:ok.length?quantile(ok,.25):null,q3:ok.length?quantile(ok,.75):null,mode,reverse:r.reverse.includes(name)}})}
