  function renderReliabilityResults(){if(!A.reliabilityResults?.length)return '';const f=x=>Number.isFinite(x)?x.toFixed(3):'—';return `<section class="analysis-inferential-history analysis-reliability-results"><h4>${uiText("תוצאות אלפא קרונבאך (")}${A.reliabilityResults.length} ${uiText("מדדים)")}</h4><p class="analysis-help">${uiText("החישוב מתבצע לכל מדד שהוגדר, על נבדקים עם תשובות מלאות לכל ההיגדים באותו מדד. פריטים הפוכים שסומנו בשלב הגדרת המדד עוברים היפוך 1–5 לפני החישוב.")}</p>${A.reliabilityResults.map((r,i)=>`<article class="analysis-stat-card analysis-inferential-result"><h4>${i+1}. ${escA(r.name)}</h4>${r.error?`<p class="analysis-alert error">${escA(r.error)}</p>`:`<div class="analysis-stat-cards"><div class="analysis-stat-card stat-0"><span>${uiText("אלפא קרונבאך")}</span><b>${f(r.alpha)}</b></div><div class="analysis-stat-card stat-1"><span>${uiText("היגדים")}</span><b>${r.itemCount}</b></div><div class="analysis-stat-card stat-2"><span>${uiText("נבדקים עם תשובות מלאות")}</span><b>${r.validN}</b></div></div><p class="analysis-result-meta">${escA(uiText(r.interpretation))}</p><div class="analysis-table-scroll analysis-spss-scroll"><table class="analysis-vars analysis-spss analysis-result-table"><thead><tr><th>${uiText("היגד")}</th><th>${uiText("מתאם פריט–סך מתוקן")}</th><th>${uiText("אלפא אם ההיגד הוסר")}</th><th>${uiText("שינוי באלפא")}</th><th>${uiText("בדיקה")}</th></tr></thead><tbody>${r.items.map(x=>`<tr><td class="spss-name">${escA(x.name)}${x.reverse?("<small> " + uiText("· היפוך 1–5") + "</small>"):''}</td><td>${f(x.correctedItemTotal)}</td><td>${f(x.alphaIfDeleted)}</td><td>${Number.isFinite(x.alphaChange)?(x.alphaChange>0?'+':'')+f(x.alphaChange):'—'}</td><td>${x.review?("<span class=\"analysis-chip id\">" + uiText("כדאי לבדוק") + "</span>"):'—'}</td></tr>`).join('')}</tbody></table></div><p class="analysis-stop-note">${escA(r.note)}</p>`}</article>`).join('')}</section>`}
