      if (A.persistTimer && !await persistAnalysisNow()) throw Error(A.saveStatus);
      await mutationQueue.catch(() => {});
      const res = await fetch('/api/state', {cache:'no-store'});
      if (!res.ok) throw Error(uiText('לא ניתן לטעון את הניתוחים השמורים.'));
      acceptSavedState(await res.json());
      const saved = S.analyses.find(record => record.id === recordId && record.type === 'analysis_workbench_state');
      if (!saved) throw Error(uiText('הניתוח שבחרת כבר אינו ברשימת השמירות.'));
      const file = S.files.find(item => item.id === saved.fileId);
      if (!file) throw Error(uiText('קובץ המקור של הניתוח אינו זמין.'));
      const fileResponse = await fetch('/api/file/' + encodeURIComponent(file.id), {cache:'no-store'});
      if (!fileResponse.ok) throw Error(uiText('לא ניתן לפתוח את קובץ המקור השמור.'));
