      A.paperId = saved.paperId || file.paperId || '';
      A.recordId = '';
      await restoreAnalysisState(file.id, recordId);
      A.existingFilesOpen = false;
      if (A.recordId !== recordId) throw Error(uiText('תוכן קובץ המקור השתנה מאז שמירת הניתוח.'));
