    if (!record || A.restorePending) return;
    const savedAt=record.updated?new Date(record.updated).toLocaleString(document.documentElement.lang || 'he',{dateStyle:'short',timeStyle:'short'}):uiText('תאריך לא ידוע');
    if (!confirm(uiText('למחוק את הניתוח השמור ״') + (record.fileName || uiText('קובץ זה')) + uiText('״, שנשמר בתאריך ')+savedAt+uiText('? קובץ ה־CSV יישאר זמין.'))) return;
